class TodoStore {
  constructor(){ this.items = new Map(); this.step = 0 }
  tick(){ this.step++ } // harness 每轮调用
  add(id, title){ this.items.set(id, {title, status:'pending', touched:this.step}) }
  update(id, patch={}){ const it=this.items.get(id); if(!it) return false
    Object.assign(it, patch, {touched:this.step}); return true }
  done(id){ return this.update(id,{status:'done'}) }
  render(){ // 每次变更后由 harness 取用注入
    const g = s => [...this.items.entries()]
      .filter(([,it])=>it.status===s)
      .map(([id,it])=>`- [${s==='done'?'x':' '}] ${it.title} (#${id})`)
    return ['## Plan', ...g('in_progress'), ...g('pending'), ...g('done')].join('\n') }
  staleHint(window=5){ const now=this.step
    return [...this.items.entries()]
      .filter(([,it])=>it.status!=='done' && now-it.touched>window)
      .map(([id,it])=>({id, title:it.title, idleSteps: now-it.touched})) }
}
// 用法：harness 每轮 todoStore.tick(); 变更后 context.append(todoStore.render());
// 循环护栏处：if (todoStore.staleHint().length) 注入『这些任务已 N 步无进展，继续还是阻塞？』
